insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about Aadhaar:','आधार के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Unique Identification Authority of India functions under the Ministry of Home Affairs.", "In its 2018 judgment, the Supreme Court struck down the provision that allowed private entities to use Aadhaar authentication on the basis of a contract."], "statements_hi": ["भारतीय विशिष्ट पहचान प्राधिकरण गृह मंत्रालय के अधीन काम करता है।", "अपने 2018 के निर्णय में उच्चतम न्यायालय ने उस प्रावधान को रद्द कर दिया जो निजी संस्थाओं को अनुबंध के आधार पर आधार प्रमाणीकरण का उपयोग करने देता था।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: the Court read down section 57 of the Aadhaar Act, while upholding Aadhaar for subsidies and benefits under section 7 and for linking with PAN. Statement 1 is wrong: the UIDAI is a statutory authority under the Ministry of Electronics and Information Technology; the Home Ministry is the tempting answer because it runs the Census and the National Population Register.','केवल कथन 2 सही है: न्यायालय ने आधार अधिनियम की धारा 57 को सीमित किया, जबकि धारा 7 के तहत सब्सिडी और लाभों के लिए और PAN से जोड़ने के लिए आधार को सही ठहराया। कथन 1 गलत है: UIDAI इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय के अधीन एक वैधानिक प्राधिकरण है; गृह मंत्रालय आकर्षक उत्तर है क्योंकि वह जनगणना और राष्ट्रीय जनसंख्या रजिस्टर चलाता है।','gov-aadhaar-uidai-section-57','original_pattern_matched','Aadhaar (Targeted Delivery of Financial and Other Subsidies, Benefits and Services) Act, 2016, sections 7, 11 and 57; Supreme Court of India -- K.S. Puttaswamy v. Union of India (2018).','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about the Aspirational Districts Programme:','आकांक्षी ज़िला कार्यक्रम के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was launched in 2018.", "It covers 112 districts.", "The districts are ranked once a year on the basis of Census data."], "statements_hi": ["इसे 2018 में शुरू किया गया।", "यह 112 ज़िलों को शामिल करता है।", "ज़िलों को जनगणना के आँकड़ों के आधार पर वर्ष में एक बार रैंक किया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Statement 3 is wrong: the programme''s method is ''competition'' through real-time monitoring -- districts are ranked every month on their improvement (''delta ranking'') across health and nutrition, education, agriculture and water resources, financial inclusion and skill development, and basic infrastructure, using data entered on the Champions of Change dashboard.','कथन 1 और 2 सही हैं। कथन 3 गलत है: कार्यक्रम का तरीका वास्तविक समय की निगरानी से ''प्रतिस्पर्धा'' है; ज़िलों को हर महीने उनके सुधार (''डेल्टा रैंकिंग'') पर रैंक किया जाता है, स्वास्थ्य और पोषण, शिक्षा, कृषि और जल संसाधन, वित्तीय समावेशन और कौशल विकास, तथा बुनियादी ढाँचे में, चैंपियंस ऑफ़ चेंज डैशबोर्ड पर दर्ज आँकड़ों के आधार पर।','gov-aspirational-districts','original_pattern_matched','NITI Aayog -- Aspirational Districts Programme.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about the Government e-Marketplace (GeM):','सरकारी ई-मार्केटप्लेस (GeM) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was launched in 2016 as an online platform for public procurement.", "It is a statutory body under the Ministry of Finance.", "Procurement through GeM is optional for central ministries even for goods and services that are available on it."], "statements_hi": ["इसे 2016 में सार्वजनिक ख़रीद के ऑनलाइन मंच के रूप में शुरू किया गया।", "यह वित्त मंत्रालय के अधीन एक वैधानिक निकाय है।", "GeM पर उपलब्ध वस्तुओं और सेवाओं के लिए भी केंद्रीय मंत्रालयों के लिए GeM से ख़रीद वैकल्पिक है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: GeM replaced the Directorate General of Supplies and Disposals. Statement 2 is wrong: it is run by the GeM Special Purpose Vehicle, a not-for-profit company under the Department of Commerce, not a statutory body. Statement 3 is wrong: the General Financial Rules, 2017 make procurement through GeM mandatory for central ministries and departments for goods and services available on it.','केवल कथन 1 सही है: GeM ने आपूर्ति और निपटान महानिदेशालय की जगह ली। कथन 2 गलत है: इसे GeM विशेष प्रयोजन वाहन चलाता है, जो वाणिज्य विभाग के अधीन एक गैर-लाभकारी कंपनी है, वैधानिक निकाय नहीं। कथन 3 गलत है: सामान्य वित्तीय नियम, 2017 केंद्रीय मंत्रालयों और विभागों के लिए GeM पर उपलब्ध वस्तुओं और सेवाओं की ख़रीद GeM से अनिवार्य बनाते हैं।','gov-gem-procurement','original_pattern_matched','General Financial Rules, 2017, Rule 149; Ministry of Commerce and Industry -- Government e-Marketplace.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about self-help groups and rural livelihoods:','स्वयं सहायता समूहों और ग्रामीण आजीविका के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Deendayal Antyodaya Yojana-National Rural Livelihoods Mission was first launched in 2016.", "NABARD''s Self-Help Group-Bank Linkage Programme began in 2005.", "The National Rural Livelihoods Mission is implemented by the Ministry of Women and Child Development."], "statements_hi": ["दीनदयाल अंत्योदय योजना-राष्ट्रीय ग्रामीण आजीविका मिशन पहली बार 2016 में शुरू किया गया।", "नाबार्ड का स्वयं सहायता समूह-बैंक लिंकेज कार्यक्रम 2005 में शुरू हुआ।", "राष्ट्रीय ग्रामीण आजीविका मिशन महिला और बाल विकास मंत्रालय द्वारा लागू किया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The mission was launched in 2011 as ''Aajeevika'', replacing the Swarnajayanti Gram Swarozgar Yojana, and was later renamed DAY-NRLM. The SHG-Bank Linkage Programme began as a NABARD pilot in 1992 and became the world''s largest microfinance programme. The mission, though it works mainly with women''s groups, is run by the Ministry of Rural Development.','कोई भी कथन सही नहीं है। मिशन 2011 में ''आजीविका'' के रूप में, स्वर्णजयंती ग्राम स्वरोज़गार योजना की जगह, शुरू हुआ और बाद में इसका नाम DAY-NRLM रखा गया। SHG-बैंक लिंकेज कार्यक्रम 1992 में नाबार्ड के प्रायोगिक कार्यक्रम के रूप में शुरू हुआ और विश्व का सबसे बड़ा सूक्ष्म वित्त कार्यक्रम बना। मिशन, हालाँकि मुख्य रूप से महिला समूहों के साथ काम करता है, ग्रामीण विकास मंत्रालय द्वारा चलाया जाता है।','gov-shg-nrlm-linkage','original_pattern_matched','Ministry of Rural Development -- DAY-NRLM; NABARD -- SHG-Bank Linkage Programme.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about e-governance in India:','भारत में ई-गवर्नेंस के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The National e-Governance Plan, approved in 2006, was built around Mission Mode Projects.", "The Digital India programme was launched in 2015.", "Common Services Centres act as access points for delivering government e-services in rural areas."], "statements_hi": ["2006 में स्वीकृत राष्ट्रीय ई-गवर्नेंस योजना मिशन मोड परियोजनाओं के इर्द-गिर्द बनी थी।", "डिजिटल इंडिया कार्यक्रम 2015 में शुरू किया गया।", "कॉमन सर्विस सेंटर ग्रामीण क्षेत्रों में सरकारी ई-सेवाएँ पहुँचाने के पहुँच-केंद्र के रूप में काम करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The NeGP created Mission Mode Projects at the Central, State and integrated levels -- passports, income tax, land records and others -- supported by State Data Centres, State Wide Area Networks and Common Services Centres run by village-level entrepreneurs. Digital India absorbed and widened the NeGP from July 2015.','तीनों कथन सही हैं। NeGP ने केंद्रीय, राज्य और एकीकृत स्तर पर मिशन मोड परियोजनाएँ बनाईं, जैसे पासपोर्ट, आयकर, भूमि अभिलेख आदि, जिन्हें राज्य डेटा केंद्रों, राज्य व्यापी क्षेत्र नेटवर्कों और ग्राम-स्तरीय उद्यमियों द्वारा चलाए जाने वाले कॉमन सर्विस सेंटरों का सहारा मिला। डिजिटल इंडिया ने जुलाई 2015 से NeGP को अपने में समाहित करके उसका विस्तार किया।','gov-negp-digital-india-csc','original_pattern_matched','Ministry of Electronics and Information Technology -- National e-Governance Plan; Digital India.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about the Good Governance Index:','सुशासन सूचकांक (Good Governance Index) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was launched in 2019, on Good Governance Day.", "It assesses States and Union Territories across ten sectors.", "It is prepared by NITI Aayog."], "statements_hi": ["इसे 2019 में सुशासन दिवस पर शुरू किया गया।", "यह दस क्षेत्रों में राज्यों और केंद्रशासित प्रदेशों का आकलन करता है।", "इसे नीति आयोग तैयार करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the sectors range from agriculture and commerce to judicial and public security and citizen-centric governance, and States are grouped by category for comparison. Statement 3 is wrong: the Index is prepared by the Department of Administrative Reforms and Public Grievances; NITI Aayog is the natural guess because it publishes several other State rankings.','कथन 1 और 2 सही हैं: क्षेत्र कृषि और वाणिज्य से लेकर न्यायिक और सार्वजनिक सुरक्षा तथा नागरिक-केंद्रित शासन तक हैं, और तुलना के लिए राज्यों को श्रेणियों में बाँटा जाता है। कथन 3 गलत है: सूचकांक प्रशासनिक सुधार और लोक शिकायत विभाग तैयार करता है; नीति आयोग स्वाभाविक अनुमान है क्योंकि वह कई अन्य राज्य रैंकिंग प्रकाशित करता है।','gov-good-governance-index','original_pattern_matched','Department of Administrative Reforms and Public Grievances -- Good Governance Index.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about pressure groups and non-governmental organisations:','दबाव समूहों और गैर-सरकारी संगठनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Pressure groups try to influence public policy without contesting elections to capture power.", "An NGO in India can be registered as a society, a trust or a not-for-profit company.", "An NGO needs registration or prior permission under the Foreign Contribution (Regulation) Act to receive foreign funds."], "statements_hi": ["दबाव समूह सत्ता पाने के लिए चुनाव लड़े बिना सार्वजनिक नीति को प्रभावित करने का प्रयास करते हैं।", "भारत में कोई NGO सोसाइटी, ट्रस्ट या गैर-लाभकारी कंपनी के रूप में पंजीकृत हो सकता है।", "विदेशी धन पाने के लिए किसी NGO को विदेशी अंशदान (विनियमन) अधिनियम के तहत पंजीकरण या पूर्व अनुमति चाहिए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The difference from political parties is that pressure groups -- trade unions, business associations, farmers'' bodies and professional groups -- seek influence, not office. NGOs are registered under the Societies Registration Act, 1860, the Indian Trusts Act or State trust laws, or as section 8 companies under the Companies Act, 2013, and must register under the FCRA before accepting foreign contributions.','तीनों कथन सही हैं। राजनीतिक दलों से अंतर यह है कि दबाव समूह, जैसे ट्रेड यूनियन, व्यापारिक संघ, किसान संगठन और पेशेवर समूह, प्रभाव चाहते हैं, पद नहीं। NGOs सोसाइटी पंजीकरण अधिनियम, 1860, भारतीय न्यास अधिनियम या राज्य न्यास कानूनों के तहत, या कंपनी अधिनियम, 2013 के तहत धारा 8 कंपनियों के रूप में पंजीकृत होते हैं, और विदेशी अंशदान स्वीकार करने से पहले उन्हें FCRA के तहत पंजीकरण कराना होता है।','gov-pressure-groups-ngos','original_pattern_matched','Societies Registration Act, 1860; Companies Act, 2013, section 8; Foreign Contribution (Regulation) Act, 2010, section 11; NCERT Class XII, Politics in India since Independence -- Rise of Popular Movements.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about Direct Benefit Transfer (DBT):','प्रत्यक्ष लाभ अंतरण (DBT) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["DBT was launched on 1 January 2013.", "The ''JAM trinity'' that supports it refers to Jan Dhan accounts, Aadhaar and mobile phones.", "The DBT Mission is located in the Ministry of Finance."], "statements_hi": ["DBT 1 जनवरी 2013 को शुरू किया गया।", "इसे सहारा देने वाली ''JAM त्रयी'' का अर्थ जन धन खाते, आधार और मोबाइल फ़ोन है।", "DBT मिशन वित्त मंत्रालय में स्थित है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: DBT began with scholarships and other schemes in selected districts and now covers several hundred schemes, including LPG subsidy and farm support. Statement 3 is wrong: the DBT Mission, first set up in the Planning Commission, was moved to the Cabinet Secretariat in 2015 so that it could coordinate across ministries.','कथन 1 और 2 सही हैं: DBT चुनिंदा ज़िलों में छात्रवृत्ति और अन्य योजनाओं से शुरू हुआ और अब LPG सब्सिडी और किसान सहायता सहित कई सौ योजनाओं को शामिल करता है। कथन 3 गलत है: DBT मिशन, जो पहले योजना आयोग में बना था, 2015 में मंत्रिमंडल सचिवालय में ले जाया गया ताकि वह मंत्रालयों के बीच समन्वय कर सके।','gov-direct-benefit-transfer','original_pattern_matched','Cabinet Secretariat -- DBT Mission.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about welfare schemes:','कल्याणकारी योजनाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["POSHAN Abhiyaan was launched in 2018 to improve nutrition outcomes for children, adolescent girls, pregnant women and lactating mothers.", "Mission Shakti is a scheme for the welfare of the Scheduled Tribes.", "Ayushman Bharat-Pradhan Mantri Jan Arogya Yojana provides health cover of up to ₹10 lakh per family per year."], "statements_hi": ["पोषण अभियान 2018 में बच्चों, किशोरियों, गर्भवती महिलाओं और स्तनपान कराने वाली माताओं के पोषण-परिणाम सुधारने के लिए शुरू किया गया।", "मिशन शक्ति अनुसूचित जनजातियों के कल्याण की योजना है।", "आयुष्मान भारत-प्रधानमंत्री जन आरोग्य योजना प्रति परिवार प्रति वर्ष ₹10 लाख तक का स्वास्थ्य कवर देती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: Mission Shakti is the Ministry of Women and Child Development''s umbrella scheme for the safety and empowerment of women, with ''Sambal'' (One Stop Centres, helplines) and ''Samarthya'' (shelter, crèche and maternity support) components. Statement 3 is wrong: PM-JAY covers up to ₹5 lakh per family per year for secondary and tertiary hospitalisation; since 2024 all citizens aged 70 and above are covered irrespective of income.','केवल कथन 1 सही है। कथन 2 गलत है: मिशन शक्ति महिला और बाल विकास मंत्रालय की महिलाओं की सुरक्षा और सशक्तीकरण की छत्र योजना है, जिसमें ''संबल'' (वन स्टॉप सेंटर, हेल्पलाइन) और ''सामर्थ्य'' (आश्रय, शिशुगृह और मातृत्व सहायता) घटक हैं। कथन 3 गलत है: PM-JAY द्वितीयक और तृतीयक अस्पताल-भर्ती के लिए प्रति परिवार प्रति वर्ष ₹5 लाख तक का कवर देती है; 2024 से 70 वर्ष और अधिक आयु के सभी नागरिक आय से अलग शामिल हैं।','gov-poshan-mission-shakti-pmjay','original_pattern_matched','Ministry of Women and Child Development -- POSHAN Abhiyaan and Mission Shakti; National Health Authority -- AB PM-JAY.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about the civil services:','सिविल सेवाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Civil Services Day, 21 April, marks the day in 1947 when Sardar Vallabhbhai Patel addressed the first batch of officers of the administrative service of independent India.", "The Prime Minister''s Awards for Excellence in Public Administration are presented on Civil Services Day.", "The All India Services Act was enacted in 1951."], "statements_hi": ["सिविल सेवा दिवस, 21 अप्रैल, 1947 के उस दिन की याद में है जब सरदार वल्लभभाई पटेल ने स्वतंत्र भारत की प्रशासनिक सेवा के अधिकारियों के पहले बैच को संबोधित किया।", "लोक प्रशासन में उत्कृष्टता के लिए प्रधानमंत्री पुरस्कार सिविल सेवा दिवस पर दिए जाते हैं।", "अखिल भारतीय सेवा अधिनियम 1951 में बनाया गया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. At Metcalfe House, Delhi, Patel called the services the ''steel frame of India''. The Act of 1951 empowers the Centre, after consulting the States, to make rules on recruitment and conditions of service for the All India Services.','तीनों कथन सही हैं। दिल्ली के मेटकाफ़ हाउस में पटेल ने सेवाओं को ''भारत का इस्पाती ढाँचा'' कहा। 1951 का अधिनियम केंद्र को, राज्यों से परामर्श के बाद, अखिल भारतीय सेवाओं की भर्ती और सेवा-शर्तों पर नियम बनाने की शक्ति देता है।','gov-civil-services-day','original_pattern_matched','All India Services Act, 1951; Department of Administrative Reforms and Public Grievances -- Civil Services Day and PM''s Awards.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about the e-Courts project:','ई-कोर्ट्स परियोजना के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its third phase was approved by the Union Cabinet in 2023.", "The National Judicial Data Grid provides data on cases pending in the courts.", "It is implemented by the Ministry of Electronics and Information Technology alone."], "statements_hi": ["इसके तीसरे चरण को केंद्रीय मंत्रिमंडल ने 2023 में स्वीकृति दी।", "राष्ट्रीय न्यायिक डेटा ग्रिड न्यायालयों में लंबित मामलों के आँकड़े देता है।", "इसे केवल इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय लागू करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Phase III aims at digital, paperless courts with e-filing, virtual hearings and digitised records, and the NJDG publishes case-level data for district courts, High Courts and the Supreme Court. Statement 3 is wrong: the project is implemented by the Department of Justice in partnership with the e-Committee of the Supreme Court, with the High Courts executing it at the ground level.','कथन 1 और 2 सही हैं: चरण III का लक्ष्य ई-फ़ाइलिंग, वर्चुअल सुनवाई और डिजिटल अभिलेखों के साथ डिजिटल, कागज़-रहित न्यायालय हैं, और NJDG ज़िला न्यायालयों, उच्च न्यायालयों और उच्चतम न्यायालय के लिए मामला-स्तरीय आँकड़े प्रकाशित करता है। कथन 3 गलत है: परियोजना उच्चतम न्यायालय की ई-समिति के साथ साझेदारी में न्याय विभाग लागू करता है, और ज़मीनी स्तर पर उच्च न्यायालय उसे क्रियान्वित करते हैं।','gov-ecourts-njdg','original_pattern_matched','Department of Justice -- e-Courts Mission Mode Project; e-Committee, Supreme Court of India.','draft'),
('upsc','Polity','Governance','statement_based','medium','Consider the following statements about the SVAMITVA scheme:','स्वामित्व (SVAMITVA) योजना के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was launched in 2020 on National Panchayati Raj Day.", "It uses drone surveys to map inhabited (''abadi'') land in villages.", "The property cards issued under it can be used to raise bank loans."], "statements_hi": ["इसे 2020 में राष्ट्रीय पंचायती राज दिवस पर शुरू किया गया।", "यह गाँवों में बसी हुई (''आबादी'') भूमि का मानचित्रण करने के लिए ड्रोन सर्वेक्षण का उपयोग करती है।", "इसके तहत जारी संपत्ति कार्डों का उपयोग बैंक ऋण लेने के लिए किया जा सकता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Rural residential land had rarely been surveyed or recorded, so owners could not prove title; the scheme, run by the Ministry of Panchayati Raj with the Survey of India and State revenue departments, gives them a ''record of rights'' that can be used as collateral and also helps Panchayats assess property tax.','तीनों कथन सही हैं। ग्रामीण आवासीय भूमि का सर्वेक्षण या अभिलेखन शायद ही कभी हुआ था, इसलिए मालिक स्वामित्व सिद्ध नहीं कर पाते थे; भारतीय सर्वेक्षण विभाग और राज्य राजस्व विभागों के साथ पंचायती राज मंत्रालय द्वारा चलाई जाने वाली यह योजना उन्हें ''अधिकार अभिलेख'' देती है, जिसका उपयोग संपार्श्विक (collateral) के रूप में हो सकता है और जो पंचायतों को संपत्ति कर आँकने में भी मदद करता है।','gov-svamitva','original_pattern_matched','Ministry of Panchayati Raj -- SVAMITVA Scheme.','draft'),
('upsc','Polity','Governance','statement_based','hard','Consider the following statements about the Supreme Court''s judgment in T.S.R. Subramanian v. Union of India (2013):','टी.एस.आर. सुब्रमण्यम बनाम भारत संघ (2013) में उच्चतम न्यायालय के निर्णय के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It directed the Union and the States to set up Civil Services Boards and to give civil servants a minimum fixed tenure.", "It held that civil servants must act on the oral instructions of political executives without placing them on record.", "It urged Parliament to enact a law regulating the postings, transfers and disciplinary proceedings of civil servants."], "statements_hi": ["इसने संघ और राज्यों को सिविल सेवा बोर्ड बनाने और सिविल सेवकों को न्यूनतम निश्चित कार्यकाल देने का निर्देश दिया।", "इसने माना कि सिविल सेवकों को राजनीतिक कार्यपालिका के मौखिक निर्देशों पर उन्हें अभिलेख में रखे बिना काम करना चाहिए।", "इसने संसद से सिविल सेवकों की पोस्टिंग, स्थानांतरण और अनुशासनात्मक कार्यवाही को नियमित करने वाला कानून बनाने का आग्रह किया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct: the petition by retired civil servants argued that frequent, arbitrary transfers undermined the neutrality of the services. Statement 2 reverses the judgment: the Court said civil servants should not act on oral instructions except in exceptional situations, and even then should record them, so that responsibility can be fixed.','कथन 1 और 3 सही हैं: सेवानिवृत्त सिविल सेवकों की याचिका का तर्क था कि बार-बार के मनमाने स्थानांतरण सेवाओं की तटस्थता को कमज़ोर करते हैं। कथन 2 निर्णय को उलट देता है: न्यायालय ने कहा कि सिविल सेवकों को असाधारण स्थितियों को छोड़कर मौखिक निर्देशों पर काम नहीं करना चाहिए, और तब भी उन्हें दर्ज करना चाहिए, ताकि ज़िम्मेदारी तय हो सके।','gov-tsr-subramanian-civil-services','original_pattern_matched','Supreme Court of India -- T.S.R. Subramanian v. Union of India (2013).','draft'),
('upsc','Polity','Governance','statement_based','hard','Consider the following statements about India''s cyber security institutions:','भारत के साइबर सुरक्षा संस्थानों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Indian Computer Emergency Response Team (CERT-In) is the national nodal agency for responding to cyber security incidents under the Information Technology Act, 2000.", "Under CERT-In''s directions of 2022, specified cyber incidents must be reported to it within six hours of being noticed.", "The National Critical Information Infrastructure Protection Centre functions under the National Technical Research Organisation.", "CERT-In functions under the National Security Council Secretariat."], "statements_hi": ["भारतीय कंप्यूटर आपात प्रतिक्रिया दल (CERT-In) सूचना प्रौद्योगिकी अधिनियम, 2000 के तहत साइबर सुरक्षा घटनाओं से निपटने की राष्ट्रीय नोडल एजेंसी है।", "CERT-In के 2022 के निर्देशों के तहत निर्दिष्ट साइबर घटनाओं की सूचना उनका पता चलने के छह घंटों के भीतर उसे देनी होती है।", "राष्ट्रीय महत्वपूर्ण सूचना अवसंरचना संरक्षण केंद्र राष्ट्रीय तकनीकी अनुसंधान संगठन के अधीन काम करता है।", "CERT-In राष्ट्रीय सुरक्षा परिषद सचिवालय के अधीन काम करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct: CERT-In works under section 70B and NCIIPC under section 70A of the IT Act, the latter protecting critical sectors such as power, banking and telecom. Statement 4 is wrong: CERT-In is part of the Ministry of Electronics and Information Technology. The National Security Council Secretariat houses the National Cyber Security Coordinator, who coordinates policy, while the Home Ministry''s Indian Cyber Crime Coordination Centre (I4C) deals with cyber crime.','कथन 1, 2 और 3 सही हैं: CERT-In IT अधिनियम की धारा 70B और NCIIPC धारा 70A के तहत काम करता है; दूसरा बिजली, बैंकिंग और दूरसंचार जैसे महत्वपूर्ण क्षेत्रों की रक्षा करता है। कथन 4 गलत है: CERT-In इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय का भाग है। राष्ट्रीय सुरक्षा परिषद सचिवालय में राष्ट्रीय साइबर सुरक्षा समन्वयक होते हैं, जो नीति का समन्वय करते हैं, जबकि गृह मंत्रालय का भारतीय साइबर अपराध समन्वय केंद्र (I4C) साइबर अपराध से निपटता है।','gov-cert-in-nciipc','original_pattern_matched','Information Technology Act, 2000, sections 70A and 70B; CERT-In Directions under section 70B(6) (April 2022).','draft'),
('upsc','Polity','Governance','statement_based','hard','Consider the following statements about social audit:','सामाजिक लेखापरीक्षा (social audit) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Kerala was the first State to enact a law on the social audit of government schemes.", "Social audit units are meant to be independent of the agencies that implement the schemes they audit.", "Social audit of government schemes is conducted by the Comptroller and Auditor-General."], "statements_hi": ["केरल सरकारी योजनाओं की सामाजिक लेखापरीक्षा पर कानून बनाने वाला पहला राज्य था।", "सामाजिक लेखापरीक्षा इकाइयाँ उन एजेंसियों से स्वतंत्र होनी चाहिए जो उनके द्वारा लेखापरीक्षित योजनाओं को लागू करती हैं।", "सरकारी योजनाओं की सामाजिक लेखापरीक्षा नियंत्रक-महालेखापरीक्षक करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: independence from the implementing department is what gives social audit credibility. Statement 1 is wrong: Meghalaya, with its Community Participation and Public Services Social Audit Act, 2017, was the first State to make social audit a legal requirement across schemes. Statement 3 is wrong: social audit is carried out by the community -- typically through the Gram Sabha, facilitated by the social audit unit -- which verifies records against what happened on the ground; the CAG''s audit is a separate, formal audit of government accounts.','केवल कथन 2 सही है: कार्यान्वयन विभाग से स्वतंत्रता ही सामाजिक लेखापरीक्षा को विश्वसनीयता देती है। कथन 1 गलत है: सामुदायिक भागीदारी और सार्वजनिक सेवा सामाजिक लेखापरीक्षा अधिनियम, 2017 के साथ मेघालय पहला राज्य था जिसने योजनाओं में सामाजिक लेखापरीक्षा को विधिक अनिवार्यता बनाया। कथन 3 गलत है: सामाजिक लेखापरीक्षा समुदाय करता है, प्रायः ग्राम सभा के ज़रिए, सामाजिक लेखापरीक्षा इकाई की सहायता से, जो अभिलेखों को ज़मीनी हकीकत से मिलाता है; CAG की लेखापरीक्षा सरकारी लेखों की एक अलग, औपचारिक लेखापरीक्षा है।','gov-social-audit','original_pattern_matched','Meghalaya Community Participation and Public Services Social Audit Act, 2017; Ministry of Rural Development -- Auditing Standards for Social Audit (2016).','draft'),
('upsc','Polity','Governance','statement_based','hard','Consider the following statements about the civil servant''s position under the Constitution:','संविधान के तहत सिविल सेवक की स्थिति के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The All India Services (Conduct) Rules, 1968 bar members of the services from taking part in politics.", "The safeguards of Article 311 extend to the employees of statutory corporations and public sector undertakings.", "Article 310 embodies the ''doctrine of pleasure'', under which civil servants hold office during the pleasure of the President or the Governor."], "statements_hi": ["अखिल भारतीय सेवा (आचरण) नियम, 1968 सेवाओं के सदस्यों को राजनीति में भाग लेने से रोकते हैं।", "अनुच्छेद 311 के सुरक्षा उपाय वैधानिक निगमों और सार्वजनिक क्षेत्र के उपक्रमों के कर्मचारियों तक विस्तृत हैं।", "अनुच्छेद 310 ''प्रसाद के सिद्धांत'' को व्यक्त करता है, जिसके तहत सिविल सेवक राष्ट्रपति या राज्यपाल के प्रसादपर्यंत पद धारण करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct: neutrality in the Conduct Rules and the pleasure doctrine of Article 310 are balanced by Article 311, which protects a civil servant from dismissal by an authority subordinate to the appointing one and without an inquiry. Statement 2 is wrong: Article 311 applies only to members of the civil services and holders of civil posts under the Union or a State; employees of corporations and PSUs, though they may be ''the State'' under Article 12, do not get its protection.','कथन 1 और 3 सही हैं: आचरण नियमों की तटस्थता और अनुच्छेद 310 के प्रसाद के सिद्धांत को अनुच्छेद 311 संतुलित करता है, जो सिविल सेवक को नियुक्ति प्राधिकारी से अधीनस्थ प्राधिकारी द्वारा और बिना जाँच के बर्ख़ास्तगी से बचाता है। कथन 2 गलत है: अनुच्छेद 311 केवल संघ या राज्य के अधीन सिविल सेवाओं के सदस्यों और सिविल पदों के धारकों पर लागू है; निगमों और PSUs के कर्मचारी, भले ही अनुच्छेद 12 के तहत ''राज्य'' हों, इसका संरक्षण नहीं पाते।','gov-civil-servant-310-311-conduct','original_pattern_matched','Constitution of India, Articles 310 and 311; All India Services (Conduct) Rules, 1968, rule 5.','draft'),
('upsc','Polity','Governance','statement_based','hard','Consider the following statements about co-operative governance:','सहकारी शासन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A separate Union Ministry of Co-operation was created in 2021.", "In 2021, the Supreme Court struck down the provisions of Part IXB relating to co-operative societies within a single State, for want of ratification by the States.", "The 97th Amendment Act, 2011 made the right to form co-operative societies a Fundamental Right under Article 19(1)(c)."], "statements_hi": ["2021 में एक अलग केंद्रीय सहकारिता मंत्रालय बनाया गया।", "2021 में उच्चतम न्यायालय ने एक ही राज्य के भीतर की सहकारी समितियों से संबंधित भाग IXB के प्रावधानों को राज्यों के अनुसमर्थन के अभाव में रद्द कर दिया।", "97वें संशोधन अधिनियम, 2011 ने सहकारी समितियाँ बनाने के अधिकार को अनुच्छेद 19(1)(c) के तहत मौलिक अधिकार बनाया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. In Union of India v. Rajendra N. Shah, the Court held that co-operative societies are a State List subject, so Part IXB needed ratification by half the States under Article 368(2); it upheld the Part only for multi-State co-operative societies, which fall in the Union List. The amendment to Article 19(1)(c) survived, as it did not need ratification.','तीनों कथन सही हैं। भारत संघ बनाम राजेंद्र एन. शाह में न्यायालय ने माना कि सहकारी समितियाँ राज्य सूची का विषय हैं, इसलिए भाग IXB को अनुच्छेद 368(2) के तहत आधे राज्यों के अनुसमर्थन की ज़रूरत थी; उसने इस भाग को केवल बहु-राज्य सहकारी समितियों के लिए सही ठहराया, जो संघ सूची में आती हैं। अनुच्छेद 19(1)(c) का संशोधन बना रहा, क्योंकि उसके लिए अनुसमर्थन आवश्यक नहीं था।','gov-cooperatives-ministry-part-ixb','original_pattern_matched','Constitution of India, Articles 19(1)(c), 43B and Part IXB; Supreme Court of India -- Union of India v. Rajendra N. Shah (2021).','draft'),
('upsc','Polity','Governance','statement_based','hard','Consider the following statements about NITI Aayog:','नीति आयोग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its Governing Council includes the Chief Ministers of all the States and of Union Territories with legislatures, and the Lieutenant Governors of the other Union Territories.", "It can form Regional Councils to address issues affecting more than one State or region.", "Its Vice-Chairperson is appointed by the President."], "statements_hi": ["इसकी शासी परिषद में सभी राज्यों और विधानमंडल वाले केंद्रशासित प्रदेशों के मुख्यमंत्री और अन्य केंद्रशासित प्रदेशों के उपराज्यपाल शामिल हैं।", "यह एक से अधिक राज्यों या क्षेत्रों को प्रभावित करने वाले मुद्दों के लिए क्षेत्रीय परिषदें बना सकता है।", "इसके उपाध्यक्ष की नियुक्ति राष्ट्रपति करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the Governing Council is meant to make NITI an instrument of ''cooperative federalism'', unlike the Planning Commission, which allocated plan funds to States. Statement 3 is wrong: NITI Aayog was set up by a Cabinet resolution, and its Vice-Chairperson, who has Cabinet rank, is appointed by the Prime Minister, its ex officio Chairperson.','कथन 1 और 2 सही हैं: शासी परिषद का उद्देश्य नीति आयोग को ''सहकारी संघवाद'' का साधन बनाना है, योजना आयोग के विपरीत, जो राज्यों को योजना-धन आवंटित करता था। कथन 3 गलत है: नीति आयोग एक मंत्रिमंडलीय संकल्प से बना, और उसके उपाध्यक्ष, जिन्हें कैबिनेट का दर्जा है, उसके पदेन अध्यक्ष प्रधानमंत्री द्वारा नियुक्त होते हैं।','gov-niti-aayog-structure','original_pattern_matched','NITI Aayog -- Cabinet Resolution of 1 January 2015.','draft'),
('upsc','Polity','Governance','mcq','medium','Good Governance Day is observed every year on:','सुशासन दिवस हर वर्ष किस दिन मनाया जाता है?','{}'::jsonb,'[{"id": "a", "body": "31 October", "body_hi": "31 अक्टूबर", "isCorrect": false}, {"id": "b", "body": "2 October", "body_hi": "2 अक्टूबर", "isCorrect": false}, {"id": "c", "body": "25 December", "body_hi": "25 दिसंबर", "isCorrect": true}, {"id": "d", "body": "26 November", "body_hi": "26 नवंबर", "isCorrect": false}]'::jsonb,2,0.66,'Good Governance Day, observed since 2014, falls on the birth anniversary of former Prime Minister Atal Bihari Vajpayee. The distractors are other national days: 31 October is National Unity Day (Sardar Patel''s birth anniversary), 2 October Gandhi Jayanti, and 26 November Constitution Day.','2014 से मनाया जाने वाला सुशासन दिवस पूर्व प्रधानमंत्री अटल बिहारी वाजपेयी की जयंती पर पड़ता है। गलत विकल्प अन्य राष्ट्रीय दिवस हैं: 31 अक्टूबर राष्ट्रीय एकता दिवस (सरदार पटेल की जयंती), 2 अक्टूबर गांधी जयंती, और 26 नवंबर संविधान दिवस।','gov-good-governance-day','original_pattern_matched','Department of Administrative Reforms and Public Grievances -- Good Governance Day.','draft'),
('upsc','Polity','Governance','mcq','medium','The Aspirational Districts Programme is anchored by:','आकांक्षी ज़िला कार्यक्रम का संचालन किसके द्वारा किया जाता है?','{}'::jsonb,'[{"id": "a", "body": "NITI Aayog", "body_hi": "नीति आयोग", "isCorrect": true}, {"id": "b", "body": "the Ministry of Rural Development", "body_hi": "ग्रामीण विकास मंत्रालय", "isCorrect": false}, {"id": "c", "body": "the Ministry of Home Affairs", "body_hi": "गृह मंत्रालय", "isCorrect": false}, {"id": "d", "body": "the Ministry of Panchayati Raj", "body_hi": "पंचायती राज मंत्रालय", "isCorrect": false}]'::jsonb,2,0.66,'NITI Aayog anchors the programme and ranks the districts, with Union ministries taking charge of particular sectors and senior officers acting as ''prabhari'' for individual districts. Its success led to the Aspirational Blocks Programme of 2023, which extends the same approach to blocks.','नीति आयोग कार्यक्रम का संचालन करता है और ज़िलों को रैंक करता है; केंद्रीय मंत्रालय विशेष क्षेत्रों का ज़िम्मा लेते हैं और वरिष्ठ अधिकारी अलग-अलग ज़िलों के ''प्रभारी'' होते हैं। इसकी सफलता से 2023 का आकांक्षी ब्लॉक कार्यक्रम आया, जो यही दृष्टिकोण खंडों तक ले जाता है।','gov-aspirational-districts-niti','original_pattern_matched','NITI Aayog -- Aspirational Districts Programme and Aspirational Blocks Programme.','draft'),
('upsc','Polity','Governance','mcq','medium','The UMANG app of the Government of India provides:','भारत सरकार का UMANG ऐप क्या प्रदान करता है?','{}'::jsonb,'[{"id": "a", "body": "a platform for storing and sharing digital documents", "body_hi": "डिजिटल दस्तावेज़ रखने और साझा करने का मंच", "isCorrect": false}, {"id": "b", "body": "a platform for filing public grievances with the Prime Minister''s Office", "body_hi": "प्रधानमंत्री कार्यालय में लोक शिकायतें दर्ज करने का मंच", "isCorrect": false}, {"id": "c", "body": "a platform for reviewing infrastructure projects", "body_hi": "बुनियादी ढाँचा परियोजनाओं की समीक्षा का मंच", "isCorrect": false}, {"id": "d", "body": "a single mobile platform for many government services", "body_hi": "कई सरकारी सेवाओं के लिए एक ही मोबाइल मंच", "isCorrect": true}]'::jsonb,2,0.66,'The Unified Mobile Application for New-age Governance, launched in 2017, brings Central and State services -- from provident fund to passport and utility payments -- onto one app. The distractors describe other platforms: document storage is DigiLocker''s function, grievances go through the grievance portal, and project reviews are done through PRAGATI.','2017 में शुरू हुआ ''यूनिफ़ाइड मोबाइल एप्लिकेशन फ़ॉर न्यू-एज गवर्नेंस'' भविष्य निधि से लेकर पासपोर्ट और बिल भुगतान तक केंद्र और राज्यों की सेवाओं को एक ऐप पर लाता है। गलत विकल्प दूसरे मंचों का वर्णन करते हैं: दस्तावेज़ रखना डिजीलॉकर का काम है, शिकायतें शिकायत पोर्टल से जाती हैं, और परियोजनाओं की समीक्षा प्रगति (PRAGATI) से होती है।','gov-umang-app','original_pattern_matched','Ministry of Electronics and Information Technology -- UMANG.','draft'),
('upsc','Polity','Governance','mcq','hard','The Freedom of Information Act, 2002, which preceded the Right to Information Act, 2005:','सूचना का अधिकार अधिनियम, 2005 से पहले आया सूचना की स्वतंत्रता अधिनियम, 2002:','{}'::jsonb,'[{"id": "a", "body": "was struck down by the Supreme Court", "body_hi": "उच्चतम न्यायालय द्वारा रद्द कर दिया गया", "isCorrect": false}, {"id": "b", "body": "was never brought into force", "body_hi": "कभी लागू नहीं किया गया", "isCorrect": true}, {"id": "c", "body": "applied only to the Union Territories", "body_hi": "केवल केंद्रशासित प्रदेशों पर लागू था", "isCorrect": false}, {"id": "d", "body": "was repealed within a year of coming into force", "body_hi": "लागू होने के एक वर्ष के भीतर निरस्त कर दिया गया", "isCorrect": false}]'::jsonb,2,0.66,'The 2002 Act received the President''s assent but was never notified, and was criticised for its wide exemptions and lack of penalties. After a sustained campaign -- including by the Mazdoor Kisan Shakti Sangathan in Rajasthan and several State RTI laws -- Parliament replaced it with the RTI Act, 2005, which repealed it.','2002 के अधिनियम को राष्ट्रपति की अनुमति मिली, पर उसे कभी अधिसूचित नहीं किया गया, और उसकी व्यापक छूटों तथा दंडों के अभाव के लिए आलोचना हुई। राजस्थान में मज़दूर किसान शक्ति संगठन सहित लगातार चले अभियान और कई राज्य RTI कानूनों के बाद संसद ने उसकी जगह RTI अधिनियम, 2005 बनाया, जिसने उसे निरस्त किया।','gov-freedom-of-information-2002','original_pattern_matched','Freedom of Information Act, 2002; Right to Information Act, 2005, section 31.','draft'),
('upsc','Polity','Governance','mcq','hard','The Multi-State Co-operative Societies (Amendment) Act, 2023 created an authority to conduct elections to multi-State co-operative societies. It is called the:','बहु-राज्य सहकारी सोसाइटी (संशोधन) अधिनियम, 2023 ने बहु-राज्य सहकारी समितियों के चुनाव कराने के लिए एक प्राधिकरण बनाया। उसे क्या कहा जाता है?','{}'::jsonb,'[{"id": "a", "body": "National Co-operative Tribunal", "body_hi": "राष्ट्रीय सहकारी अधिकरण", "isCorrect": false}, {"id": "b", "body": "Co-operative Ombudsman", "body_hi": "सहकारी लोकपाल", "isCorrect": false}, {"id": "c", "body": "Co-operative Election Authority", "body_hi": "सहकारी निर्वाचन प्राधिकरण", "isCorrect": true}, {"id": "d", "body": "National Co-operative Development Corporation", "body_hi": "राष्ट्रीय सहकारी विकास निगम", "isCorrect": false}]'::jsonb,2,0.66,'The Co-operative Election Authority was set up to hold free and fair board elections, a long-standing problem in co-operatives. The same Act also created a Co-operative Ombudsman -- but that office handles members'' complaints, not elections -- while the National Co-operative Development Corporation (1963) is a financing body.','सहकारी निर्वाचन प्राधिकरण बोर्ड के स्वतंत्र और निष्पक्ष चुनाव कराने के लिए बना, जो सहकारी समितियों की पुरानी समस्या रही है। उसी अधिनियम ने सहकारी लोकपाल भी बनाया, पर वह सदस्यों की शिकायतें देखता है, चुनाव नहीं; जबकि राष्ट्रीय सहकारी विकास निगम (1963) एक वित्तपोषण निकाय है।','gov-cooperative-election-authority','original_pattern_matched','Multi-State Co-operative Societies (Amendment) Act, 2023; Ministry of Co-operation.','draft'),
('upsc','Polity','Governance','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Aadhaar is not proof of citizenship.", "assertion_hi": "आधार नागरिकता का प्रमाण नहीं है।", "reason": "Aadhaar is issued to residents of India, who need not be citizens.", "reason_hi": "आधार भारत के निवासियों को जारी किया जाता है, जिनका नागरिक होना ज़रूरी नहीं है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Any person who has resided in India for 182 days in the preceding year can enrol, so the number establishes identity and residence, not nationality; section 9 of the Act says in so many words that it confers no right of citizenship or domicile.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। कोई भी व्यक्ति जो पिछले वर्ष में 182 दिन भारत में रहा हो, नामांकन करा सकता है, इसलिए यह संख्या पहचान और निवास स्थापित करती है, राष्ट्रीयता नहीं; अधिनियम की धारा 9 स्पष्ट शब्दों में कहती है कि यह नागरिकता या अधिवास का कोई अधिकार नहीं देता।','gov-aadhaar-not-citizenship','original_pattern_matched','Aadhaar (Targeted Delivery of Financial and Other Subsidies, Benefits and Services) Act, 2016, sections 2(v), 3 and 9.','draft'),
('upsc','Polity','Governance','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "E-governance removes the need for grievance redress mechanisms.", "assertion_hi": "ई-गवर्नेंस शिकायत निवारण तंत्रों की आवश्यकता को समाप्त कर देता है।", "reason": "E-governance reduces face-to-face contact between citizens and officials and leaves a digital record of transactions.", "reason_hi": "ई-गवर्नेंस नागरिकों और अधिकारियों के बीच आमने-सामने के संपर्क को कम करता है और लेन-देन का डिजिटल अभिलेख छोड़ता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. Less discretion and a digital trail do reduce opportunities for harassment and corruption, but digital systems create their own problems -- exclusion of people without connectivity or digital skills, authentication failures and data errors -- which is why grievance redress remains essential alongside them.','कथन-I गलत है पर कथन-II सही है। कम विवेकाधिकार और डिजिटल अभिलेख उत्पीड़न और भ्रष्टाचार के अवसर घटाते हैं, पर डिजिटल व्यवस्थाएँ अपनी समस्याएँ भी पैदा करती हैं, जैसे कनेक्टिविटी या डिजिटल कौशल के बिना लोगों का बहिष्करण, प्रमाणीकरण की विफलता और आँकड़ों की त्रुटियाँ; इसीलिए उनके साथ शिकायत निवारण ज़रूरी बना रहता है।','gov-egovernance-grievance-redress','original_pattern_matched','Second Administrative Reforms Commission, Eleventh Report: Promoting e-Governance (2008).','draft'),
('upsc','Polity','Governance','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Direct Benefit Transfer has reduced leakages in the delivery of subsidies.", "assertion_hi": "प्रत्यक्ष लाभ अंतरण ने सब्सिडी वितरण में रिसाव को कम किया है।", "reason": "Under DBT, benefits are first credited to the District Collector''s account and then distributed to the beneficiaries.", "reason_hi": "DBT के तहत लाभ पहले ज़िला कलेक्टर के खाते में जमा होते हैं और फिर लाभार्थियों में बाँटे जाते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. DBT cuts leakages precisely because it removes intermediaries: benefits are credited straight into the beneficiary''s bank or post-office account, usually Aadhaar-seeded, which also weeds out duplicate and fictitious beneficiaries.','कथन-I सही है पर कथन-II गलत है। DBT रिसाव इसलिए कम करता है कि वह बिचौलियों को हटा देता है: लाभ सीधे लाभार्थी के बैंक या डाकघर खाते में, जो प्रायः आधार से जुड़ा होता है, जमा होते हैं, जिससे दोहरे और फ़र्ज़ी लाभार्थी भी हट जाते हैं।','gov-dbt-leakages-direct-credit','original_pattern_matched','Cabinet Secretariat -- DBT Mission.','draft'),
('upsc','Polity','Governance','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Lateral entrants at the level of Joint Secretary in the Government of India are appointed on contract.", "assertion_hi": "भारत सरकार में संयुक्त सचिव स्तर पर पार्श्व प्रवेश (lateral entry) वाले अधिकारी अनुबंध पर नियुक्त होते हैं।", "reason": "They are appointed for a fixed tenure, normally three years, extendable to five years.", "reason_hi": "उन्हें एक निश्चित कार्यकाल के लिए, सामान्यतः तीन वर्ष, जिसे पाँच वर्ष तक बढ़ाया जा सकता है, नियुक्त किया जाता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "reason_2": "They are recruited through the Civil Services Examination.", "reason_2_hi": "उनकी भर्ती सिविल सेवा परीक्षा के ज़रिए होती है।"}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": false}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": true}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb,2,0.66,'Only one of Statements II and III is correct -- Statement II -- and it explains Statement I: lateral entry brings specialists from outside the services for a fixed term, which is why the appointment is contractual. Statement III is wrong: candidates are selected by the UPSC through a separate advertisement, application and interview process, not through the Civil Services Examination. A 2024 advertisement was withdrawn after criticism that such posts did not follow reservation rules.','कथन II और III में से केवल एक, कथन II, सही है और वह कथन I की व्याख्या करता है: पार्श्व प्रवेश सेवाओं के बाहर से विशेषज्ञों को निश्चित अवधि के लिए लाता है, इसीलिए नियुक्ति संविदात्मक होती है। कथन III गलत है: उम्मीदवारों का चयन UPSC एक अलग विज्ञापन, आवेदन और साक्षात्कार प्रक्रिया से करता है, सिविल सेवा परीक्षा से नहीं। 2024 का एक विज्ञापन इस आलोचना के बाद वापस लिया गया कि ऐसे पदों पर आरक्षण नियमों का पालन नहीं होता।','gov-lateral-entry-contract','original_pattern_matched','Department of Personnel and Training -- Lateral recruitment at Joint Secretary level; Union Public Service Commission advertisements (2018-2024).','draft'),
('upsc','Polity','Governance','match_the_following','medium','Consider the following pairs of programmes and the Union Ministries or Departments responsible for them:','कार्यक्रमों और उनके लिए ज़िम्मेदार केंद्रीय मंत्रालयों या विभागों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Jal Jeevan Mission", "2. POSHAN Abhiyaan", "3. Ayushman Bharat-PM-JAY", "4. PM Gati Shakti National Master Plan"], "list_1_hi": ["1. जल जीवन मिशन", "2. पोषण अभियान", "3. आयुष्मान भारत-PM-JAY", "4. पीएम गति शक्ति राष्ट्रीय मास्टर प्लान"], "list_2": ["Ministry of Jal Shakti", "Ministry of Women and Child Development", "Ministry of Health and Family Welfare", "Ministry of Power"], "list_2_hi": ["जल शक्ति मंत्रालय", "महिला और बाल विकास मंत्रालय", "स्वास्थ्य और परिवार कल्याण मंत्रालय", "विद्युत मंत्रालय"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct; PM-JAY is implemented through the National Health Authority under the Health Ministry. Pair 4 is wrong: PM Gati Shakti, a GIS-based platform for integrated infrastructure planning across ministries, is anchored by the Department for Promotion of Industry and Internal Trade under the Ministry of Commerce and Industry.','तीन युग्म सही हैं; PM-JAY स्वास्थ्य मंत्रालय के अधीन राष्ट्रीय स्वास्थ्य प्राधिकरण के माध्यम से लागू होती है। युग्म 4 गलत है: पीएम गति शक्ति, मंत्रालयों के बीच एकीकृत बुनियादी ढाँचा योजना का GIS-आधारित मंच, वाणिज्य और उद्योग मंत्रालय के उद्योग और आंतरिक व्यापार संवर्धन विभाग द्वारा संचालित है।','gov-programmes-ministries-pairs','original_pattern_matched','Ministry of Jal Shakti; Ministry of Women and Child Development; National Health Authority; Department for Promotion of Industry and Internal Trade -- PM Gati Shakti.','draft'),
('upsc','Polity','Governance','match_the_following','medium','Consider the following pairs of indices and the bodies that prepare them:','सूचकांकों और उन्हें तैयार करने वाले निकायों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. SDG India Index", "2. State Energy Efficiency Index", "3. Export Preparedness Index", "4. Ease of Living Index"], "list_1_hi": ["1. SDG इंडिया सूचकांक", "2. राज्य ऊर्जा दक्षता सूचकांक", "3. निर्यात तैयारी सूचकांक", "4. जीवन सुगमता सूचकांक"], "list_2": ["NITI Aayog", "Bureau of Energy Efficiency", "NITI Aayog", "Ministry of Housing and Urban Affairs"], "list_2_hi": ["नीति आयोग", "ऊर्जा दक्षता ब्यूरो", "नीति आयोग", "आवास और शहरी कार्य मंत्रालय"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. NITI Aayog''s State rankings (SDG India Index, Export Preparedness Index and others) are tools of ''competitive federalism''; the Bureau of Energy Efficiency prepares the energy index with the Alliance for an Energy Efficient Economy; and the Ease of Living Index ranks cities under the Housing and Urban Affairs Ministry. A student expecting one mismatch will fall for ''Only three pairs''.','चारों युग्म सही हैं। नीति आयोग की राज्य रैंकिंग (SDG इंडिया सूचकांक, निर्यात तैयारी सूचकांक आदि) ''प्रतिस्पर्धी संघवाद'' के साधन हैं; ऊर्जा दक्षता ब्यूरो ऊर्जा सूचकांक एलायंस फ़ॉर एन एनर्जी एफ़िशिएंट इकोनॉमी के साथ तैयार करता है; और जीवन सुगमता सूचकांक आवास और शहरी कार्य मंत्रालय के तहत शहरों को रैंक करता है। जो विद्यार्थी एक बेमेल की अपेक्षा करता है, वह ''केवल तीन युग्म'' के जाल में फँसेगा।','gov-indices-bodies-pairs','original_pattern_matched','NITI Aayog -- SDG India Index and Export Preparedness Index; Bureau of Energy Efficiency -- State Energy Efficiency Index; Ministry of Housing and Urban Affairs -- Ease of Living Index.','draft'),
('upsc','Polity','Governance','match_the_following','hard','Consider the following pairs of government digital systems and their purposes:','सरकारी डिजिटल प्रणालियों और उनके उद्देश्यों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. PFMS", "2. e-Office", "3. SPARROW", "4. e-HRMS"], "list_1_hi": ["1. PFMS", "2. ई-ऑफ़िस", "3. SPARROW", "4. e-HRMS"], "list_2": ["Tracking funds released under government schemes down to the final recipient", "Paperless handling of files in government offices", "Online recording of the annual performance appraisal reports of officers", "GIS-based planning of infrastructure projects"], "list_2_hi": ["सरकारी योजनाओं के तहत जारी धन को अंतिम प्राप्तकर्ता तक ट्रैक करना", "सरकारी कार्यालयों में फ़ाइलों का कागज़-रहित संचालन", "अधिकारियों की वार्षिक कार्य-मूल्यांकन रिपोर्टों का ऑनलाइन अभिलेखन", "बुनियादी ढाँचा परियोजनाओं की GIS-आधारित योजना"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct. The Public Financial Management System, run by the Controller General of Accounts, underpins DBT; e-Office, developed by the National Informatics Centre, moves files digitally; and SPARROW (Smart Performance Appraisal Report Recording Online Window) handles appraisals of IAS and other officers. Pair 4 is wrong: e-HRMS is the electronic human resource management system for central government employees -- leave, service records and the like.','तीन युग्म सही हैं। महालेखा नियंत्रक द्वारा संचालित सार्वजनिक वित्तीय प्रबंधन प्रणाली DBT का आधार है; राष्ट्रीय सूचना-विज्ञान केंद्र द्वारा विकसित ई-ऑफ़िस फ़ाइलों को डिजिटल रूप से आगे बढ़ाता है; और SPARROW IAS और अन्य अधिकारियों के मूल्यांकन को संभालता है। युग्म 4 गलत है: e-HRMS केंद्र सरकार के कर्मचारियों के लिए इलेक्ट्रॉनिक मानव संसाधन प्रबंधन प्रणाली है, जैसे अवकाश, सेवा अभिलेख आदि।','gov-digital-systems-pairs','original_pattern_matched','Controller General of Accounts -- PFMS; National Informatics Centre -- e-Office; Department of Personnel and Training -- SPARROW and e-HRMS.','draft'),
('upsc','Polity','Governance','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Self-help groups are small voluntary groups, mostly of women, that pool their savings and access bank credit together.", "MyGov is an online platform for citizens to take part in governance by giving suggestions and feedback."], "statements_hi": ["स्वयं सहायता समूह छोटे स्वैच्छिक समूह हैं, जिनमें अधिकतर महिलाएँ होती हैं, जो अपनी बचत एकत्र करते हैं और मिलकर बैंक ऋण पाते हैं।", "MyGov नागरिकों के लिए सुझाव और प्रतिक्रिया देकर शासन में भाग लेने का एक ऑनलाइन मंच है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. SHGs, usually of ten to twenty members, have become the main channel for rural women''s credit and livelihoods. MyGov, launched in 2014, invites citizens to discuss policies, take part in tasks and competitions, and comment on draft proposals.','दोनों कथन सही हैं। SHG, प्रायः दस से बीस सदस्यों के, ग्रामीण महिलाओं के ऋण और आजीविका का मुख्य माध्यम बन गए हैं। 2014 में शुरू हुआ MyGov नागरिकों को नीतियों पर चर्चा करने, कार्यों और प्रतियोगिताओं में भाग लेने, और मसौदा प्रस्तावों पर टिप्पणी करने के लिए आमंत्रित करता है।','gov-shg-mygov-easy','original_pattern_matched','NABARD -- Self-Help Groups; Ministry of Electronics and Information Technology -- MyGov.','draft')
